selector_to_html = {"a[href=\"getting_started/installation.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Installation<a class=\"headerlink\" href=\"#installation\" title=\"Link to this heading\">#</a></h1><h2>Choose a platform<a class=\"headerlink\" href=\"#choose-a-platform\" title=\"Link to this heading\">#</a></h2><p>Each platform is selected by a single build variable, <code class=\"docutils literal notranslate\"><span class=\"pre\">FLAGOS_ACCELERATOR</span></code>, and each platform has its own execution path:</p>", "a[href=\"#torch-fl\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Torch-FL<a class=\"headerlink\" href=\"#torch-fl\" title=\"Link to this heading\">#</a></h1><p>Torch-FL (<code class=\"docutils literal notranslate\"><span class=\"pre\">torch_fl</span></code>) is a PyTorch device plugin for the FlagOS software stack. It exposes a single <code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code> device that routes operators among reusable native kernels, portable compiler kernels, vendor-native implementations, and explicit CPU fallback, so the same PyTorch program runs across accelerators without workload changes.</p><p><a data-lightbox=\"image-set\" href=\"_images/torch-fl.png\">\n<img alt=\"Torch-FL architecture\" src=\"_images/torch-fl.png\"/></a>\n</p>", "a[href=\"reference/compatibility.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Compatibility and Platform Support<a class=\"headerlink\" href=\"#compatibility-and-platform-support\" title=\"Link to this heading\">#</a></h1><h2>Status definitions<a class=\"headerlink\" href=\"#status-definitions\" title=\"Link to this heading\">#</a></h2>", "a[href=\"overview/overview.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Torch-FL Overview<a class=\"headerlink\" href=\"#torch-fl-overview\" title=\"Link to this heading\">#</a></h1><p><code class=\"docutils literal notranslate\"><span class=\"pre\">torch_fl</span></code> is a custom PyTorch device plugin built on the <code class=\"docutils literal notranslate\"><span class=\"pre\">PrivateUse1</span></code> extension mechanism. It registers <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagGems\">FlagGems</a> high-performance Triton operators, vendor-native operator libraries, and CUDA compatibility kernels behind one device name: <code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code>.</p><p>Accelerator vendors ship different runtimes, compiler stacks, and PyTorch integration strategies. Torch-FL hides those differences behind a unified runtime and operator-routing layer, so users program against standard PyTorch APIs and a single device name, and the plugin selects a kernel implementation per operator based on platform capability and configuration.</p>", "a[href=\"architecture/profiler.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Profiler Integration<a class=\"headerlink\" href=\"#profiler-integration\" title=\"Link to this heading\">#</a></h1><p><code class=\"docutils literal notranslate\"><span class=\"pre\">torch.profiler</span></code> supports the <code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code> device through a device tracer compiled into the wheel. A trace from <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.profiler.profile(activities=[CPU,</span> <span class=\"pre\">PrivateUse1])</span></code> is structurally equivalent to the trace of the same workload on <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.cuda</span></code>:</p>", "a[href=\"architecture/distributed.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Distributed Collectives<a class=\"headerlink\" href=\"#distributed-collectives\" title=\"Link to this heading\">#</a></h1><p>Torch-FL provides distributed support for the <code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code> device through <code class=\"docutils literal notranslate\"><span class=\"pre\">ProcessGroupFlagOS</span></code>, a native <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.distributed.ProcessGroup</span></code> subclass. It is registered at import, so <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.distributed.init_process_group(\"flagos\")</span></code> works with no <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.distributed.*</span></code> monkeypatching.</p>", "a[href=\"architecture/torch-compile.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">torch.compile Integration<a class=\"headerlink\" href=\"#torch-compile-integration\" title=\"Link to this heading\">#</a></h1><p>The <code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code> device supports <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.compile</span></code> for automatic kernel fusion and reduced dispatch overhead. The graph stays on the <code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code> device: there is no device round trip and no copy at the graph boundary.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
